function testHoursById() {
  const shifts = [
    { member: [{ id: "rec1", name: "Ava" }], hours: 1 },
    { member: [{ id: "rec2", name: "Ava" }], hours: 2 },
    { member: [{ id: "rec1", name: "Ava" }], hours: 1.5 },
    { member: null, hours: 3 }
  ]
  console.log(JSON.stringify(hoursById(shifts)))
}

function hoursById(shifts) {
  const totals = {}
  for (let i = 0; i < shifts.length; i++) {
    const links = shifts[i].member
    if (links !== null) {
      const id = links[0].id
      if (totals[id] === undefined) {
        totals[id] = 0
      }
      totals[id] += shifts[i].hours
    }
  }
  return totals
}
